        void flush() { for (var o : managed.values()) table.put(o.id, o.status); }

        /** The managed instance for id: the persistence context first, else one SELECT; null when the row is missing. */
        Order find(long id) {
            var known = managed.get(id);
            if (known != null) return known;
            selects++;
            String status = table.get(id);
            if (status == null) return null;
            var loaded = new Order(id, status);
            managed.put(id, loaded);
            return loaded;
        }

