        test("merging onto an instance that is already managed needs no select (boundary)", () -> {
            var s = session();
            var managed = s.find(1L);
            var result = s.save(new Order(1L, "paid"));
            ok(result == managed, "merge must copy onto the managed instance");
            eq(List.of(managed.status, s.selects), List.of("paid", 1));
        });
        test("saving the managed instance itself returns it", () -> {
            var s = session();
            var managed = s.find(1L);
            managed.status = "packed";
            ok(s.save(managed) == managed, "save of a managed entity must return it");
            s.flush();
            eq(s.table.get(1L), "packed");
        });
        test("find of a missing id is null", () -> eq(session().find(9L), null));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

